<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuesto Ixtlahuacán | Acceso</title><link rel="stylesheet" href="css/styles.css"><link rel="stylesheet" href="css/login.css"></head>
<body class="login-body">
<main class="login-shell">
  <section class="login-visual">
    <div class="login-brand"><img src="img/ixtla/main_logo_al_frente.png" alt="Ixtlahuacán"><span>Presupuesto Municipal</span></div>
    <div class="photo-mosaic">
      <figure class="photo-main"><img src="img/ixtla/portadaLogin.png" alt="Ixtlahuacán"><figcaption><strong>Control claro de cada peso</strong><span>Presupuesto, salidas, solicitudes y seguimiento en un solo lugar.</span></figcaption></figure>
      <figure><img src="img/ixtla/municipio_1.png" alt="Municipio"></figure>
      <figure><img src="img/ixtla/municipio_2.png" alt="Municipio"></figure>
    </div>
    <div class="login-feature-row"><div><span>🏛️</span><b>Por departamento</b></div><div><span>🔎</span><b>Trazabilidad</b></div><div><span>📱</span><b>Diseño móvil</b></div></div>
  </section>
  <section class="login-panel">
    <div class="login-card">
      <div class="mobile-logo"><img src="img/ixtla/main_logo.png" alt="Ixtlahuacán"></div>
      <span class="eyebrow">PLATAFORMA MUNICIPAL</span><h1>Bienvenido</h1><p class="muted">Ingresa con tu cuenta de Presupuesto Ixtlahuacán.</p>
      <form id="loginForm" autocomplete="on"><label>Usuario o correo<input name="username" id="username" autocomplete="username" placeholder="admin.demo" required></label><label>Contraseña<div class="password-field"><input name="password" id="password" type="password" autocomplete="current-password" placeholder="••••••••" required><button type="button" id="togglePassword" aria-label="Mostrar contraseña">👁</button></div></label><div id="loginError" class="alert error hidden"></div><button class="btn btn-primary btn-lg" type="submit">Entrar a Presupuesto</button></form>
      <div class="demo-box"><div><span class="status-dot"></span><strong>Acceso de demostración</strong></div><p>Administrador: <code>admin.demo</code><br>La contraseña se configura fuera del repositorio.</p><button class="btn btn-soft" type="button" id="fillDemo">Usar usuario demo</button></div>
      <small class="login-footnote">Acceso controlado · Las acciones quedan registradas en bitácora.</small>
    </div>
  </section>
</main><script src="js/login.js"></script></body></html>
